  // Try calling any that look like tool creators
  for (const k of relevant.slice(0, 5)) {
    try {
      const r = m[k]();
      if (Array.isArray(r) && r[0]?.name) {
        console.log(`${k}() returns tools:`, r.map(t=>t.name).join(', '));
      }
    } catch(e) {}
  }
} catch(e) {
  console.error('Error:', e.message.slice(0, 400));
}
EOF

