# Now get the remaining tools: read/write/edit/exec/process/memory_search/memory_get
node --input-type=module << 'EOF'
const m = await import('/usr/lib/node_modules/openclaw/dist/compact-1mmJ_KWL.js');

// Find functions that create individual tools (single-tool returns)
const singleTools = [];
const fns = Object.entries(m).filter(([k,v]) => typeof v === 'function');

for (const [k, fn] of fns) {
  for (const args of [[], [{}], [null], [{config:{}}]]) {
    try {
      const r = fn(...args);
      if (r && typeof r === 'object' && !Array.isArray(r) && 'name' in r && 'description' in r && (r.input_schema || r.inputSchema || r.parameters)) {
        singleTools.push({
          key: k,
          name: r.name,
          description: r.description?.slice(0, 60),
          schema: r.input_schema || r.inputSchema || r.parameters
        });
        break;
      }
    } catch(e) {}
  }
}
console.log('Single-tool factories:', singleTools.map(t => `${t.key}=>${t.name}`).join(', '));
process.stdout.write('\n' + JSON.stringify(singleTools, null, 2));
EOF

