# Extract exec and process tool schemas at runtime by loading from compact bundle
node --input-type=module << 'EOF'
const m = await import('/usr/lib/node_modules/openclaw/dist/compact-1mmJ_KWL.js');

// We know "tt" creates the gateway/messaging toolset. 
// Let's try ALL functions that return single objects with name+description+schema
const found = [];
const fns = Object.entries(m).filter(([k,v]) => typeof v === 'function');
const tried = new Set();

for (const [k, fn] of fns) {
  if (tried.has(fn)) continue;
  tried.add(fn);
  for (const args of [[], [{}], [{workspaceDir:'/tmp', agentDir:'/tmp'}]]) {
    try {
      const r = fn(...args);
      if (r && !Array.isArray(r) && typeof r === 'object' && typeof r.name === 'string' && r.name.length > 1 && (r.input_schema || r.inputSchema || r.parameters)) {
        const schema = r.input_schema || r.inputSchema || r.parameters;
        found.push({name: r.name, description: (r.description||'').slice(0,80), schema});
        break;
      }
    } catch(e) {}
  }
}

console.log('Found single-tool results:', found.map(f=>f.name).join(', '));
process.stdout.write(JSON.stringify(found, null, 2));
EOF

# The compact bundle has exec/process etc in it. Let's search directly.
# Look at what the "tt" function specifically calls and also search for exec/read/write tool names in the bundle
node --input-type=module << 'EOF'
const m = await import('/usr/lib/node_modules/openclaw/dist/compact-1mmJ_KWL.js');

// The tt function returns 16 tools. Let's now look for the createOpenClawCodingTools equivalent
// that returns ALL tools including exec, read, write, edit, process, memory
const fns = Object.entries(m).filter(([k,v]) => typeof v === 'function');
const tried = new Set();

for (const [k, fn] of fns) {
  if (tried.has(fn)) continue;
  tried.add(fn);
  for (const args of [{}, {workspaceDir:'/tmp',agentDir:'/tmp',config:{}}, null]) {
    try {
      const r = args === null ? fn() : fn(args);
      if (Array.isArray(r) && r.length > 16 && r[0]?.name) {
        console.log(`${k}(${JSON.stringify(args)?.slice(0,40)}) => ${r.length} tools: ${r.map(t=>t.name).join(', ')}`);
        process.stdout.write(JSON.stringify(r.map(t=>({name:t.name,description:t.description,input_schema:t.input_schema||t.inputSchema||t.parameters})), null, 2));
        break;
      }
    } catch(e) {}
  }
}
console.log('done');
EOF

