        },
        "job": {
          "additionalProperties": true,
          "type": "object",
          "properties": {}
        },
        "jobId": {
          "type": "string"
        },
        "id": {
          "type": "string"
        },
        "patch": {
          "additionalProperties": true,
          "type": "object",
          "properties": {}
        },
        "text": {
          "type": "string"
        },
